-- Full India state/city import for TimesAuto.
-- Source: sptspl fuel scraper DB (dbapipanel), filtered to city rows
-- with >=500 price rows AND data in the last 30 days. That filter drops
-- 265 contaminated rows -- the scraper had stored a fallback list of
-- major cities (Bangalore, Chennai, Mumbai...) under 8 states that have
-- no fuel data of their own, which would have applied e.g. Sikkim road
-- tax to a Bangalore buyer. Genuine same-name cities in different
-- states (Aurangabad MH/BR, Hamirpur HP/UP) are preserved.
--
-- Existing rows are matched by name and left untouched, so the 4 states,
-- 11 cities and the 7 tables holding city_id foreign keys keep their ids.
BEGIN;
-- Noida is in Uttar Pradesh, not Rajasthan. On-road price derives from
-- state road tax, so this row would quote Noida buyers a Rajasthan figure.
UPDATE cities SET state_id=(SELECT id FROM states WHERE name='Uttar Pradesh') WHERE lower(name)='noida';
COMMIT;
-- Verify:  SELECT (SELECT count(*) FROM states) states, (SELECT count(*) FROM cities) cities;
